#include <stdio.h>
#include <stdlib.h>

#define MAXN 100005

long long key[MAXN];
unsigned int prio[MAXN];
int left[MAXN], right[MAXN], sz[MAXN];
int nodeCnt = 0;
int root = -1;

unsigned int seed = 123456789;
unsigned int rnd() {
    seed ^= seed << 13;
    seed ^= seed >> 17;
    seed ^= seed << 5;
    return seed;
}

int szof(int t) {
    return t == -1 ? 0 : sz[t];
}

void update(int t) {
    if (t != -1) {
        sz[t] = 1 + szof(left[t]) + szof(right[t]);
    }
}

int rotateRight(int t) {
    int u = left[t];
    left[t] = right[u];
    right[u] = t;
    update(t);
    update(u);
    return u;
}

int rotateLeft(int t) {
    int u = right[t];
    right[t] = left[u];
    left[u] = t;
    update(t);
    update(u);
    return u;
}

int insert(int t, int node) {
    if (t == -1) return node;
    if (key[node] < key[t]) {
        left[t] = insert(left[t], node);
        if (prio[left[t]] < prio[t]) {
            t = rotateRight(t);
        }
    } else {
        right[t] = insert(right[t], node);
        if (prio[right[t]] < prio[t]) {
            t = rotateLeft(t);
        }
    }
    update(t);
    return t;
}

int query(int t, long long d) {
    if (t == -1) return 0;
    if (key[t] <= d) {
        return szof(left[t]) + 1 + query(right[t], d);
    } else {
        return query(left[t], d);
    }
}

int main() {
    int N;
    if (scanf("%d", &N) != 1) return 0;
    long long prev = 0;
    for (int i = 1; i <= N; i++) {
        long long x, y;
        scanf("%lld %lld", &x, &y);
        long long ax = x + prev;
        long long ay = y + prev;
        long long d = ax * ax + ay * ay;
        int p = query(root, d);
        printf("%d\n", p);

        int node = nodeCnt++;
        key[node] = d;
        prio[node] = rnd();
        left[node] = right[node] = -1;
        sz[node] = 1;
        root = insert(root, node);

        prev = p;
    }
    return 0;
}
